import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BU4O3IzQ.js";const r="/penn-notes/news/2026-08/7bb11a1390f2.png",i="/penn-notes/news/2026-08/f1fe60b0454b.jpg",o="/penn-notes/news/2026-08/022f2f20dff0.png",c="/penn-notes/news/2026-08/898f7f58376b.jpg",l="/penn-notes/news/2026-08/258cb187037a.png",p="/penn-notes/news/2026-08/a95767b385ee.png",h="/penn-notes/news/2026-08/9c0fdf0bd93f.png",m="/penn-notes/news/2026-08/9243f96b3796.jpg",I=JSON.parse('{"title":"AI 动态 · 2026-08-13","description":"","frontmatter":{"title":"AI 动态 · 2026-08-13","date":"2026-08-13T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-13.md","filePath":"news/2026-08/ai-news-2026-08-13.md","lastUpdated":1787416107000}'),d={name:"news/2026-08/ai-news-2026-08-13.md"};function u(g,e,b,f,w,k){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-动态-·-2026-08-13" tabindex="-1">AI 动态 · 2026-08-13 <a class="header-anchor" href="#ai-动态-·-2026-08-13" aria-label="Permalink to &quot;AI 动态 · 2026-08-13&quot;">​</a></h1><blockquote><p>截至 2026-08-13。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="微软合并-copilot-应用并砍掉失败-ai-功能" tabindex="-1">微软合并 Copilot 应用并砍掉失败 AI 功能 <a class="header-anchor" href="#微软合并-copilot-应用并砍掉失败-ai-功能" aria-label="Permalink to &quot;微软合并 Copilot 应用并砍掉失败 AI 功能&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-13">2026-08-13</time></p><p><img src="'+r+'" alt="配图"></p><p>微软正在简化 Copilot 产品线，将面向消费者和企业的应用合并为单一应用，同时砍掉 AI 生成播客、Group Chats、Deep Research 以及 Mico 角色等表现不佳的功能。此举旨在整合资源，聚焦核心 AI 助手体验。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/13/microsoft-kills-off-unsuccessful-ai-features-while-merging-its-separate-copilot-apps/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="苹果洽谈向出版商付费-为-siri-提供实时新闻" tabindex="-1">苹果洽谈向出版商付费，为 Siri 提供实时新闻 <a class="header-anchor" href="#苹果洽谈向出版商付费-为-siri-提供实时新闻" aria-label="Permalink to &quot;苹果洽谈向出版商付费，为 Siri 提供实时新闻&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-13">2026-08-13</time></p><p><img src="'+i+'" alt="配图"></p><p>据《华尔街日报》报道，苹果正在与出版商洽谈，计划支付费用以让 Siri 能够提供最新新闻。据悉，苹果已考虑为此项服务提供九位数的预算，以增强 Siri 在信息获取方面的竞争力。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/13/apple-in-talks-to-pay-publishers-to-provide-siri-with-current-news-report/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="ai-编程创企-cognition-洽谈-400-亿美元估值融资" tabindex="-1">AI 编程创企 Cognition 洽谈 400 亿美元估值融资 <a class="header-anchor" href="#ai-编程创企-cognition-洽谈-400-亿美元估值融资" aria-label="Permalink to &quot;AI 编程创企 Cognition 洽谈 400 亿美元估值融资&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-13">2026-08-13</time></p><p><img src="'+o+'" alt="配图"></p><p>据报道，AI 编程初创公司 Cognition 正在洽谈新一轮融资，估值可能达到 400 亿美元。就在几个月前，该公司刚以 260 亿美元估值完成 10 亿美元融资。此轮融资若完成，将再次刷新 AI 编程赛道的估值纪录。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/12/ai-coding-startup-cognition-reportedly-already-in-talks-to-raise-at-40b-valuation/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="anthropic-上市估值或达-2-万亿美元" tabindex="-1">Anthropic 上市估值或达 2 万亿美元 <a class="header-anchor" href="#anthropic-上市估值或达-2-万亿美元" aria-label="Permalink to &quot;Anthropic 上市估值或达 2 万亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-08-13">2026-08-13</time></p><p><img src="'+c+'" alt="配图"></p><p>得益于快速的营收增长，市场对 Anthropic 的 IPO 寄予厚望，认为其有望成为历史上规模最大的上市，估值可能达到 2 万亿美元。这一预期反映了投资者对 Claude 系列模型商业化潜力的高度看好。</p><p class="news-entry-source"><a href="https://arstechnica.com/ai/2026/08/anthropic-could-be-worth-2-trillion-when-it-goes-public/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="openai-预览-ultrafast-模式-gpt-5-6-sol-速度提升-14-倍" tabindex="-1">OpenAI 预览 Ultrafast 模式：GPT-5.6 Sol 速度提升 14 倍 <a class="header-anchor" href="#openai-预览-ultrafast-模式-gpt-5-6-sol-速度提升-14-倍" aria-label="Permalink to &quot;OpenAI 预览 Ultrafast 模式：GPT-5.6 Sol 速度提升 14 倍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-08-13">2026-08-13</time></p><p><img src="'+l+'" alt="配图"></p><p>OpenAI 预览新的 API 服务层级 Ultrafast，由 Cerebras 提供支持，可将 GPT-5.6 Sol 的推理速度提升至 14 倍，输出速率高达每秒 750 tokens。该模式旨在将速度转化为竞争优势，为对延迟敏感的应用提供新的选择。</p><p class="news-entry-source"><a href="https://openai.com/index/previewing-ultrafast" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="deepseek-发布官方-v4-pro-模型-加速扩张" tabindex="-1">DeepSeek 发布官方 V4 Pro 模型，加速扩张 <a class="header-anchor" href="#deepseek-发布官方-v4-pro-模型-加速扩张" aria-label="Permalink to &quot;DeepSeek 发布官方 V4 Pro 模型，加速扩张&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Reuters</span><time datetime="2026-08-13">2026-08-13</time></p><p>DeepSeek 正式发布 V4 Pro 模型，标志着其在 AI 领域的扩张步伐加快。尽管有评论认为该旗舰模型更新在部分领域表现平平，但在网络安全方面表现突出。此举将进一步加剧开源与闭源模型的竞争。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMirgFBVV95cUxNVzBOcmxUZXZzV20xU1pZMnI1X0JKRzV1SUJwcGhzaE1JZDZfUTZqVDZMVXNhUHFoY295SHZuLWZZbTlXa1AtUmI2dkRhRWliRXFBYzdZQlROdUVzZ2dNc2pHLUhvdTFBSVpSTW9SaHBQUnJubTdMX2FQUkhHTDhiUGtiZDUxLTRQXzRrZERqSzlOSXZpMWYxUzVWeXFCdW1HZEVWbWMtVDhFU1BCSkE?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="meta-发布-muse-glimmer-面向本地-pc-的轻量级-ai-模型" tabindex="-1">Meta 发布 Muse Glimmer：面向本地 PC 的轻量级 AI 模型 <a class="header-anchor" href="#meta-发布-muse-glimmer-面向本地-pc-的轻量级-ai-模型" aria-label="Permalink to &quot;Meta 发布 Muse Glimmer：面向本地 PC 的轻量级 AI 模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">WSMV</span><time datetime="2026-08-13">2026-08-13</time></p><p>Meta 发布名为 Muse Glimmer 的全新 AI 模型，专为本地 PC 设计。该模型旨在提供强大的 AI 能力，同时降低对云端算力的依赖，为桌面端应用带来更高效、更私密的 AI 体验。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMipAFBVV95cUxPYTM4WmtQU1JPQktaZllxWkk1ZGE0WUZ6S01SVFNqUHlXUGUxd1VCM2thcWpkdmRQal9XVmhzQ1FQSUpaX3dmM1piX2FKTmh3OFhfZDZraUlyRUV0cEV1Vm9XdktuMWxsM2dKZ2VzdnM0TnhCTG5JUUUxXzhMVV9UZGVadWlPOEY0c0VkaFBPai1lY1UwbHFaaWtoNTVmcXV2VHR5aw?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="google-发布-gemini-omni-多模态模型" tabindex="-1">Google 发布 Gemini Omni 多模态模型 <a class="header-anchor" href="#google-发布-gemini-omni-多模态模型" aria-label="Permalink to &quot;Google 发布 Gemini Omni 多模态模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Tech Buzz</span><time datetime="2026-08-13">2026-08-13</time></p><p>Google 正式推出 Gemini Omni 模型，专家对其细节进行解读。该模型是 Google 在 AI 领域的最新力作，旨在通过更强的多模态能力巩固其在搜索和云服务中的竞争优势。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMikAFBVV95cUxNeEZsajRxMy00N3J2LXBOVzJvTGZORXBhbWdQQUtiTlhPQ3BPdWRMYXRaSGpmc3E5bXptNTY3amJqcE9DSmZyV2dhQ2pRc1NXWnpjNTBKWkRxc29OODhOdWdnZVBINm82YUhVLU5TQWYwSGVtV1BldnFtUEJ4RFFDdGFDY3pONVRSb1RqQ0oybm4?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="hugging-face-分享复现-2200-篇-icml-论文的经验" tabindex="-1">Hugging Face 分享复现 2200 篇 ICML 论文的经验 <a class="header-anchor" href="#hugging-face-分享复现-2200-篇-icml-论文的经验" aria-label="Permalink to &quot;Hugging Face 分享复现 2200 篇 ICML 论文的经验&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-08-13">2026-08-13</time></p><p><img src="'+p+'" alt="配图"></p><p>Hugging Face 发布博客，分享了其复现 2200 篇 ICML 论文的旅程与收获。该项目旨在通过大规模复现推动开放科学，揭示了当前 AI 研究可复现性的现状与挑战，为社区提供了宝贵的实践经验。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/icml-2026-open-reproductions" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="nvidia-开源-switchyard-跨模型流量路由工具" tabindex="-1">NVIDIA 开源 Switchyard：跨模型流量路由工具 <a class="header-anchor" href="#nvidia-开源-switchyard-跨模型流量路由工具" aria-label="Permalink to &quot;NVIDIA 开源 Switchyard：跨模型流量路由工具&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">NVIDIA-NeMo/Switchyard</span><time datetime="2026-08-13">2026-08-13</time></p><p><img src="'+h+'" alt="配图"></p><p>NVIDIA 开源 Switchyard，一个让 LLM 应用在模型和提供商之间路由流量的工具，同时保持原生 OpenAI 和 Anthropic API 兼容性。它支持灵活的模型选择、基准测试和成本/性能优化，为开发者提供了更大的控制权。</p><p class="news-entry-source"><a href="https://github.com/NVIDIA-NeMo/Switchyard" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="tanstack-table-v9-测试版发布-tree-shakable-特性与更低内存" tabindex="-1">TanStack Table V9 测试版发布：Tree-Shakable 特性与更低内存 <a class="header-anchor" href="#tanstack-table-v9-测试版发布-tree-shakable-特性与更低内存" aria-label="Permalink to &quot;TanStack Table V9 测试版发布：Tree-Shakable 特性与更低内存&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-13">2026-08-13</time></p><p><img src="'+m+'" alt="配图"></p><p>TanStack Table V9 发布 beta 版本，这是一款用于多种 JavaScript 框架的 headless UI 表格库。新版本采用按需注册的特性模型，实现 Tree-Shakable，并引入 TanStack Store 状态管理，显著降低内存使用。迁移过程是渐进式的，并提供兼容旧版本的工具。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/sw9Wgh5VPpzpuUmQvFo1?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div>',8)])])}const _=a(d,[["render",u]]);export{I as __pageData,_ as default};
